  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json"
  },
  "transform": [
    {
      "sort": [
        {
          "field": "date"
        }
      ],
      "window": [
        {
          "field": "users",
          "op": "mean",
          "as": "7-Day Average"
        }
      ],
      "frame": [-6, 0]
    },
    {
      "fold": [
        "users",
        "7-Day Average"
      ],
      "as": [
        "Metric",
        "Value"
      ]
    }
  ],
  "mark": "line",
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "title": "Date"
    },
    "y": {
      "field": "Value",
      "type": "quantitative",
      "title": "Daily Active Users"
    },
    "color": {
      "field": "Metric",
      "type": "nominal",
      "scale": {
        "scheme": "colorblind"
      }
    }
  }
}
```

